private let chatReactionDebugLogs = true
/// Presentation-layer sampling of the last cells across a send flight (see
/// startSendFlightSampler). Diagnostic-only; the reported jump is mid-animation, which
/// no settle-time log can capture.
private let chatListSendFlightSamplerEnabled = true

public final class ChatListView: UIView, UICollectionViewDataSource,
  UICollectionViewDelegateFlowLayout
{
  public var onViewportChanged = NativeEventDispatcher()
  public var onNativeEvent = NativeEventDispatcher()
  var onAgentRunStateChanged: (() -> Void)?

  @objc public var surfaceId: String = "" {
    didSet {
      if !surfaceId.isEmpty {
        ChatListRegistry.shared.register(surfaceId: surfaceId, view: self)
      }
    }
  }

  private let flowLayout: ChatTimelineLayout
  let collectionView: UICollectionView
  /// The wallpaper is NOT owned here. `ChatMainView` hosts the single `ChatWallpaperView`
  /// behind every page; this list is transparent over it. This view only borrows the flat
  /// raster for the frosted backdrop behind bubbles.
  weak var wallpaperSource: ChatWallpaperView?
  private let scrollToneOverlay = UIView()
  private let scrollToneTopView = ChatWallpaperEdgeEffectView(edge: .top)
  private let scrollToneBottomView = ChatWallpaperEdgeEffectView(edge: .bottom)
  var rows: [ChatListRow] = [] {
    // Deliberately does not read `oldValue`: an observer that touches it forces a copy
    // of the whole array on every `rows[i] = …`, and this one runs on the hottest
    // property in the file.
    didSet {
      coreRowLookup = nil
      if rows.isEmpty {
        updateSecureChatEmptyStateVisibility()
      } else {
        secureChatEmptyStateView.isHidden = true
      }
    }
  }
  private let secureChatEmptyStateView = UIStackView()
  private let secureChatEmptyStateIcon = UIImageView()
  private let secureChatEmptyStateTitle = UILabel()
  private let secureChatEmptyStateSubtitle = UILabel()
  /// Identity → row for the core's measurement provider, built on demand.
  ///
  /// The provider used to answer with `rows.first { $0.messageId == id || $0.key == id }`
  /// — a full scan of the transcript per row measured. The core measures every message
  /// in a fresh window, so opening a 979-row chat ran ~958,000 string comparisons on the
  /// main thread before a single bubble was drawn, and it grew with the square of the
  /// transcript.
  ///
  /// Correctness comes from the observer above rather than from remembering to refresh
  /// it: any assignment to `rows`, including a subscript write, drops the index, so it
  /// can only ever answer for the transcript currently mounted. A stale row here would
  /// be a *wrong* height rather than a missing one, which is the worse failure.
  private var coreRowLookup: [String: ChatListRow]?
  private var appearance = ChatListAppearance.current
  private var lastRawAppearance: [String: Any]?
  private var queuedAppearanceAfterSendTransition: ChatListAppearance?
  private var shouldAutoScroll = true
  private var previousOffsetY: CGFloat = 0.0
  private var skipNextTransitionScrollCorrection = false
  private var lastKnownViewportWidth: CGFloat = 0.0
  private var lastKnownViewportHeight: CGFloat = 0.0
  private var contentPaddingTop: CGFloat = sectionTopInset
  private var requestedContentPaddingBottom: CGFloat = sectionBottomInset
  /// Clearance under the last row, as a **section inset** — part of `contentSize`, not
  /// `contentInset` (see `logViewportCoverage`).
  ///
  /// It is assigned from six places and starts at `sectionBottomInset` (14) before the
  /// composer has ever been laid out, then becomes `barHeight + keyboardHeight` on the
  /// first layout pass that has a bar. That is a real two-phase settle on chat open, and
  /// because it is a section inset it moves `contentSize` and therefore everything below
  /// it. Every change is recorded so `recordViewportDrift` can name the mutation instead
  /// of reporting the category — "blame=height" is where an investigation starts,
  /// "pad 14→56 (inputBar)" is where it ends.
  private var contentPaddingBottom: CGFloat = sectionBottomInset {
    didSet { noteBottomPaddingChange(from: oldValue) }
  }
  /// Keyboard/panel clearance. Rides `contentInset.bottom` so it never enters
  /// `contentSize`; composed with the agent-pin reserve by `applyTranscriptBottomInset`.
  private var keyboardClearance: CGFloat = 0.0
  /// Everything occluding the bottom of the transcript: composer inset plus keyboard.
  private var transcriptBottomClearance: CGFloat { contentPaddingBottom + keyboardClearance }
  /// Geometry mutations since the last viewport checkpoint, newest last.
  private var pendingGeometryCauses: [String] = []
  private var isApplyingRowsUpdate = false
  private var pendingStreamingTextLayoutInvalidation = false
